Trusted execution environment (TEE).ejemplo:
/* Interfaz EDL (Intel SGX): separación explícita entre mundo confiable y host */
enclave {
    trusted {
        public sgx_status_t ecall_decrypt([in, size=len] const uint8_t* ct,
                                          size_t len, [out, size=32] uint8_t* out);
    };
    untrusted {
        void ocall_audit_log([in, string] const char* msg);
    };
};

mTLS.ejemplo:
# Servidor Nginx exigiendo y validando certificado de cliente (mTLS)
server {
    listen 443 ssl;
    ssl_protocols TLSv1.3;
    ssl_certificate     /etc/ssl/server.crt;
    ssl_certificate_key /etc/ssl/server.key;
    ssl_client_certificate /etc/ssl/ca-clients.crt;
    ssl_verify_client   on;
    ssl_verify_depth    2;
}
